import urllib.request
import re
url = 'https://books.rakuten.co.jp/search?g=001&sitem=9784253030939'
req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
try:
    with urllib.request.urlopen(req) as res:
        html = res.read().decode('utf-8')
        match = re.search(r'class=\'title.*?\'>(.*?)</a>', html, re.IGNORECASE | re.DOTALL)
        if not match:
            match = re.search(r'class=.title.*?.>(.*?)</a>', html, re.IGNORECASE | re.DOTALL)
        if match: 
            print('Rakuten Book Title:', match.group(1).strip())
        else:
            print('Not found')
except Exception as e: print(e)
